// Package vectors carries the Aertun Evidence Protocol's version 1 test
// vectors in the binary, so `aertun conform` checks a verifier without a
// copy of this repository. The files are generated by internal/aep's
// TestVectors, which also requires that they reproduce byte for byte.
package vectors

import "embed"

// FS holds the vectors, one JSON file each, in the order they are named.
//
//go:embed *.json
var FS embed.FS
